import { writeFileSync, mkdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { leagueFixtures } from "../src/data/league.ts";

// Every exported event set is deterministically generated by the same seeded
// fixture definition used in the browser. No user-provided match data is trusted.
mkdirSync("backend/data", { recursive: true });
for (const [index, fixture] of leagueFixtures.entries()) {
  const { match } = fixture;
  const payload = {
    schema_version: 1,
    match_id: match.metadata.id,
    duration_seconds: match.metadata.durationSeconds,
    seed: index === 0 ? 2026 : 2026 + index * 917,
    event_count: match.events.length,
    home_team: { id: match.metadata.homeTeam.id, name: match.metadata.homeTeam.name },
    away_team: { id: match.metadata.awayTeam.id, name: match.metadata.awayTeam.name },
    events: match.events,
  };
  const digest = createHash("sha256").update(JSON.stringify(payload.events)).digest("hex");
  const document = { ...payload, events_sha256: digest };
  const filename = index === 0 ? "replay.json" : `replay-${match.metadata.id}.json`;
  writeFileSync(`backend/data/${filename}`, JSON.stringify(document) + "\n", "utf8");
  console.log(`Exported ${payload.match_id}: ${payload.event_count} events, hash ${digest}`);
}
